PREFIXES={
(166,'cs'):{
0:('Materiál:','Lehká tkaná směs bavlny s měkkým, jemně mačkaným omakem a čistým, prodyšným splýváním — pro rodinné dny v teplém počasí od rán na pláži po večeře na zahradě.'),
1:('Rodinný příběh:','Sladěný komplet pro čtyři rodinné role — maminka a dívky ve vzdušných šatech se slonovinovými pruhy, tatínek a chlapci ve stejné pruhované košili se šalvějovými šortkami s kapsami. Jedna paleta, tři druhy oblečení a celá rodina sladěná dohromady.'),
2:('Vzor:','Ivory Stripe Cargo — jemně strukturované svislé slonovinové pruhy doplněné tlumenými šalvějovými šortkami s kapsami. Klidná pobřežní paleta, připravená na focení.'),
3:('Design:','Zvolte <em>šaty</em> pro maminku a dívky ve vrstveném střihu bez rukávů se zavazováním u výstřihu; vyberte <em>košili</em> pro tatínka a chlapce v uvolněném střihu s krátkými rukávy, límcem a knoflíky vpředu; zvolte <em>šortky</em> jako navlékací šalvějové cargo šortky s prostornými kapsami s klopami.'),
4:('Péče:','Perte v pračce ve studené vodě na šetrný program s podobnými barvami. Sušte na šňůře nebo v sušičce při nízké teplotě. V případě potřeby žehlete naruby při nízké teplotě. Nebělte.'),
5:('Rozsah velikostí:','Dívky 1–10 let · Chlapci 1–10 let · Maminka S–L · Tatínek S–3XL — přesné rozměry najdete níže.')},
(166,'da'):{
0:('Stof:','Let vævet bomuldsblanding med en blød, let krøllet overflade og et enkelt, åndbart fald — skabt til familiens dage i varmt vejr, fra strandmorgener til middage i haven.'),
1:('Familiens historie:','Et koordineret sæt til fire familieroller — mor og pigerne i en luftig elfenbensstribet kjole, far og drengene i en matchende elfenbensstribet skjorte med salviegrønne cargoshorts. Én palet, tre beklædningsdele og hele familien klædt i samme stil.'),
2:('Mønster:','Ivory Stripe Cargo — diskrete lodrette striber i elfenben med blød struktur, kombineret med dæmpede salviegrønne cargoshorts. En rolig, kystinspireret palet, der er klar til billeder.'),
3:('Design:','Vælg <em>kjolen</em> til mor og pigerne for en ærmeløs silhuet i lag med bindebånd ved halsen; vælg <em>skjorten</em> til far og drengene for en afslappet kortærmet skjorte med krave og knapper foran; vælg <em>shortsene</em> for salviegrønne cargoshorts, der er lette at trække på, med rummelige lommer med klap.'),
4:('Pleje:','Maskinvaskes koldt på skåneprogram med lignende farver. Hænges til tørre eller tørretumbles ved lav varme. Stryges om nødvendigt på vrangen ved lav varme. Må ikke bleges.'),
5:('Størrelser:','Piger 1–10 år · Drenge 1–10 år · Mor S–L · Far S–3XL — se de præcise mål nedenfor.')},
(166,'no'):{
0:('Stoff:','Lett vevd bomullsblanding med en myk, lett krøllet overflate og et rent, pustende fall — laget for familiedager i varmt vær, fra morgener på stranden til middager i hagen.'),
1:('Familiens historie:','Et koordinert sett til fire familieroller — mamma og jentene i en luftig elfenbensstripet kjole, pappa og guttene i en matchende elfenbensstripet skjorte med salviegrønne cargoshorts. Én palett, tre plaggtyper og hele familien stylet sammen.'),
2:('Mønster:','Ivory Stripe Cargo — vertikale elfenbensstriper med myk struktur, kombinert med dempede salviegrønne cargoshorts. En rolig, kystinspirert palett som er klar for bilder.'),
3:('Design:','Velg <em>kjolen</em> til mamma og jentene for en ermeløs silhuett i lag med knyting ved halsen; velg <em>skjorten</em> til pappa og guttene for en avslappet kortermet skjorte med krage og knapper foran; velg <em>shortsen</em> for salviegrønne cargoshorts som er lette å trekke på, med romslige klafflommer.'),
4:('Stell:','Maskinvaskes kaldt på skånsomt program med lignende farger. Heng til tørk eller tørk i tørketrommel på lav varme. Stryk på vrangen med lav varme ved behov. Må ikke blekes.'),
5:('Størrelser:','Jenter 1–10 år · Gutter 1–10 år · Mor S–L · Far S–3XL — se nøyaktige mål nedenfor.')},
(166,'el'):{
0:('Ύφασμα:','Ελαφρύ υφαντό μείγμα βαμβακιού με απαλή, ελαφρώς τσαλακωμένη υφή και καθαρό, διαπνέον πέσιμο — για οικογενειακές ημέρες με ζεστό καιρό, από τα πρωινά στην παραλία μέχρι τα δείπνα στην αυλή.'),
1:('Οικογενειακή ιστορία:','Ένα συντονισμένο σύνολο για τέσσερις οικογενειακούς ρόλους — η μαμά και τα κορίτσια με αέρινο φόρεμα με ιβουάρ ρίγες, ο μπαμπάς και τα αγόρια με ασορτί ριγέ ιβουάρ πουκάμισο και σορτς cargo στο χρώμα του φασκόμηλου. Μία παλέτα, τρία είδη ρούχων, όλη η οικογένεια συντονισμένη.'),
2:('Μοτίβο:','Ivory Stripe Cargo — κάθετες ιβουάρ ρίγες με απαλή υφή, συνδυασμένες με σορτς cargo σε διακριτικό χρώμα φασκόμηλου. Μια ήρεμη, παραθαλάσσια παλέτα, έτοιμη για φωτογραφίες.'),
3:('Σχεδίαση:','Επιλέξτε το <em>φόρεμα</em> για τη μαμά και τα κορίτσια, με αμάνικη γραμμή σε στρώσεις και δέσιμο στη λαιμόκοψη· επιλέξτε το <em>πουκάμισο</em> για τον μπαμπά και τα αγόρια, σε άνετη γραμμή με κοντά μανίκια, γιακά και κουμπιά μπροστά· επιλέξτε το <em>σορτς</em> για ένα ευκολοφόρετο cargo στο χρώμα του φασκόμηλου με ευρύχωρες τσέπες με καπάκι.'),
4:('Φροντίδα:','Πλύσιμο στο πλυντήριο με κρύο νερό, σε απαλό πρόγραμμα και με παρόμοια χρώματα. Στέγνωμα σε απλώστρα ή σε στεγνωτήριο σε χαμηλή θερμοκρασία. Αν χρειάζεται, σιδέρωμα από την ανάποδη σε χαμηλή θερμοκρασία. Μην χρησιμοποιείτε λευκαντικό.'),
5:('Μεγέθη:','Κορίτσια 1–10 ετών · Αγόρια 1–10 ετών · Μητέρα S–L · Πατέρας S–3XL — δείτε τις ακριβείς μετρήσεις παρακάτω.')},
(176,'el'):{
0:('Ύφασμα:','Ελαφρύ υφαντό ύφασμα με αέρινη αίσθηση και δροσερό πέσιμο — για ζεστά πρωινά, βόλτες στον κήπο και άνετες ημέρες ταξιδιού.'),
1:('Οικογενειακή ιστορία:','Ένα ασορτί σύνολο για τέσσερις οικογενειακούς ρόλους — οι μαμάδες και τα κορίτσια με συντονισμένο φλοράλ φόρεμα με τετράγωνη λαιμόκοψη, οι μπαμπάδες και τα αγόρια με ασορτί κοντομάνικο πουκάμισο με γιακά, όλοι στο ίδιο μοτίβο Bluebell Meadow.'),
2:('Μοτίβο:','Bluebell Meadow — γαλαζολίλα άνθη και κλαδάκια σε απαλό κίτρινο, σκορπισμένα ανάμεσα σε φρέσκα πράσινα φύλλα σε ανοιχτό γαλάζιο φόντο.'),
3:('Σχεδίαση:','Επιλέξτε το <em>φόρεμα</em> με ελαστικό μπούστο σφηκοφωλιά, τετράγωνη λαιμόκοψη, κοντά φουσκωτά μανίκια και απαλή, πλούσια φούστα· επιλέξτε το <em>πουκάμισο</em> σε άνετη γραμμή, με κοντά μανίκια, κουμπιά μπροστά και προσεγμένο γιακά. Το τζιν σορτς που εμφανίζεται με το πουκάμισο του μπαμπά χρησιμοποιείται μόνο για την παρουσίαση και δεν περιλαμβάνεται.'),
4:('Φροντίδα:','Πλύσιμο στο πλυντήριο με κρύο νερό, σε απαλό πρόγραμμα και με παρόμοια χρώματα. Στέγνωμα σε απλώστρα ή σε στεγνωτήριο σε χαμηλή θερμοκρασία. Αν χρειάζεται, σιδέρωμα από την ανάποδη σε χαμηλή θερμοκρασία. Μην χρησιμοποιείτε λευκαντικό.'),
5:('Μεγέθη:','Κορίτσια και αγόρια από 1–2 έως 9–10 ετών · Μητέρα S–2XL · Πατέρας S–4XL — δείτε τις ακριβείς μετρήσεις παρακάτω.')},
(176,'fi'):{
0:('Kangas:','Kevyt kudottu kangas, jossa on ilmava tuntu ja keveä laskeutuvuus — lämpimiin aamuihin, puutarhakävelyihin ja vaivattomiin matkapäiviin.'),
1:('Perheen tarina:','Yhteensopiva kokonaisuus neljälle perheroolille — äideillä ja tytöillä neliöpääntiellä varustettu kukkamekko, isillä ja pojilla vastaava lyhythihainen kauluspaita, kaikissa sama Bluebell Meadow -kuosi.'),
2:('Kuosi:','Bluebell Meadow — sinivioletteja kukkia ja voinkeltaisia oksia tuoreiden vihreiden lehtien lomassa vaalean taivaansinisellä pohjalla.'),
3:('Malli:','Valitse <em>mekko</em>, jossa on jousto-ommeltu yläosa, neliöpääntie, lyhyet puhvihihat ja pehmeä, runsas hameosa; valitse <em>paita</em>, jos haluat rennon lyhythihaisen mallin, jossa on napitus edessä ja siisti kaulus. Isän paidan kanssa kuvissa näkyvät farkkushortsit ovat vain asun esittelyä varten eivätkä sisälly tuotteeseen.'),
4:('Hoito:','Konepesu kylmässä vedessä hellävaraisella ohjelmalla samanväristen kanssa. Kuivaa pyykkinarulla tai kuivausrummussa alhaisessa lämpötilassa. Silitä tarvittaessa nurjalta puolelta alhaisessa lämpötilassa. Älä valkaise.'),
5:('Koot:','Tytöt ja pojat 1–2-vuotiaista 9–10-vuotiaisiin · Äiti S–2XL · Isä S–4XL — tarkat mitat alla.')},
(176,'ro'):{
0:('Țesătură:','Țesătură ușoară, cu o senzație aerisită la atingere și o cădere lejeră — pentru dimineți calde, plimbări în grădină și zile de călătorie fără griji.'),
1:('Povestea familiei:','Un set asortat pentru patru roluri în familie — mamele și fetele într-o rochie florală cu decolteu pătrat, tații și băieții într-o cămașă asortată cu mânecă scurtă și guler, toate cu același imprimeu Bluebell Meadow.'),
2:('Imprimeu:','Bluebell Meadow — flori albastru-violet și rămurele galben-pal presărate printre frunze verzi proaspete, pe un fundal bleu deschis.'),
3:('Design:','Alegeți <em>rochia</em> cu corsaj elastic încrețit, decolteu pătrat, mâneci scurte bufante și o fustă amplă, moale; alegeți <em>cămașa</em> pentru o croială lejeră cu mânecă scurtă, nasturi în față și guler îngrijit. Pantalonii scurți din denim prezentați cu cămașa tatălui sunt folosiți doar pentru stilizare și nu sunt incluși.'),
4:('Îngrijire:','Spălați la mașină cu apă rece, pe program delicat, împreună cu culori similare. Uscați pe sârmă sau în uscător la temperatură scăzută. Dacă este necesar, călcați pe dos la temperatură scăzută. Nu folosiți înălbitor.'),
5:('Mărimi:','Fete și băieți de la 1–2 ani până la 9–10 ani · Mamă S–2XL · Tată S–4XL — măsurătorile exacte sunt mai jos.')}
}
